  "279940": "Use: Places a Toxin Study that contains healing potions and anti-venom, and provides all of the benefits of a First Aid Kit. Requires a Campfire nearby. May be placed over a First Aid Kit to replace it. All camping features share a cooldown of 1 hr.",
  "279941": "Use: Places a Tanning Rack that allows the creation of certain reagents, and provides all of the benefits of a Camp Tent. Requires a Campfire nearby. May be placed over a Camp Tent to replace it. All camping features share a cooldown of 1 hr.",
  "279943": "Use: Places a Spinning Wheel that allows the creation of certain reagents, and provides all the benefits of a Faction Banner. Requires a Campfire nearby. May be placed over a Faction Banner to replace it. All camping features share a cooldown of 1 hr.",
  "279944": "Use: Constructs a sharpening wheel that grants you and others sitting nearby 34 increased Strength, mutually exclusive with Strength of Earth Totem. Requires a Campfire nearby. All camping features share a cooldown of 1 hr.",
  "279945": "Use: Places a Sewing Machine usable for recipes that require it, and provides all of the benefits of a Camp Tent. Requires a Campfire nearby. May be placed over a Camp Tent to replace it. All camping features share a cooldown of 1 hr.",
  "279949": "Use: Summons a Repair Bot that allows you and others nearby to buy reagents and repair gear. Requires a Campfire nearby. May be placed over a Reagent Bot to replace it. All camping features share a cooldown of 1 hr.",
  "279950": "Use: Summons a Reagent Bot that allows you and others nearby to purchase reagents. Requires a Campfire nearby. All camping features share a cooldown of 1 hr.",
  "279951": "Use: Places a Plague Doctor's Laboratory that contains healing potions and poultices, and provides all of the benefits of a First Aid Kit. Requires a Campfire nearby. May be placed over a First Aid Kit to replace it. All camping features share a cooldown of 1 hr.",
  "279955": "Use: Places a Master Forge usable for recipes that require it, and provides all of the benefits of a Sharpening Wheel. Requires a Campfire nearby. May be placed over a Sharpening Wheel to replace it. All camping features share a cooldown of 1 hr.",
  "279956": "Use: Constructs a mana well that allows you and others sitting nearby to regenerate 29 Mana every 5 sec, muutally exclusive with Blessing of Wisdom. Requires a Campfire nearby. All camping features share a cooldown of 1 hr.",
  "279957": "Use: Lay out Cookie's Feast that contains Stamina-boosting food. Requires a Cooking Fire nearby. All camping features share a cooldown of 1 hr.",
  "279959": "Use: Places a Loom usable for recipes that require it, and provides all the benefits of a Faction Banner. Requires a Campfire nearby. May be placed over a Faction Banner to replace it. All camping features share a cooldown of 1 hr.",
  "279961": "Use: Builds a journeyman campfire that allows cooking and the placement of up to 5 additional camp features. Players sitting or crafting nearby for 1 min will gain benefits from other camp features.",
  "279968": "Use: Unpacks a first aid kit that allows you and others sitting nearby to gain 56 increased Stamina, mutually exclusive with Power Word: Fortitude. Requires a Campfire nearby. All camping features share a cooldown of 1 hr.",
  "279970": "Use: Places a fermenter that allows the creation of certain reagents, and provides all of the benefits of a Mana Well. Requires a Campfire nearby. May be placed over a Mana Well to replace it. All camping features share a cooldown of 1 hr.",
  "279972": "Use: Unrolls a banner that allows you and other members of the Horde sitting nearby to gain 32 increased Spirit, mutually exclusive with Divine Spirit. Requires a Campfire nearby. All camping features share a cooldown of 1 hr.",
  "279973": "Use: Unrolls a banner that allows you and other members of the Alliance sitting nearby to gain 32 increased Spirit, mutually exclusive with Divine Spirit. Requires a Campfire nearby. All camping features share a cooldown of 1 hr.",
  "279974": "Use: Builds an expert campfire that allows cooking and the placement of up to 10 additional camp features. Players sitting or crafting nearby for 1 min will gain benefits from other camp features.",
  "279976": "Use: Other Requires Enchanting (20) Use: Summons an enchanted lute that allows you and others sitting nearby to gain 308 Armor, 13 increase to all stats, and 22 increase to all resistances, mutually exclusive with Mark of the Wild. Requires a Campfire nearby. All camping features share a cooldown of 1 hr. (60 Min Cooldown)",
  "279978": "Use: Builds a tent that allows you and others sitting nearby to increase Rested experience to 5% of a level. No effect if Rested experience already exceeds that value. Requires a Campfire nearby. All camping features share a cooldown of 1 hr.",
  "279981": "Use: Builds a basic campfire that allows cooking and the placement of up to 3 additional camp features. Players sitting or crafting nearby for 1 min will gain benefits from other camp features.",
  "279982": "Use: Places an Iron Oven required for the most advanced cooking recipes. Requires a Cooking Fire nearby. All camping features share a cooldown of 1 hr.",
  "279985": "Use: Other Requires Enchanting (140) Use: Places an Arcane Salvager that enables more efficient disenchanting, and provides all the benefits of an Enchanted Lute. Requires a Campfire nearby. May be placed over an Enchanted Lute to replace it. All camping features share a cooldown of 1 hr. (60 Min Cooldown)",
  "279987": "Use: Other Requires Enchanting (300) Use: Places an Arcane Forge usable for recipes that require it, and provides all the benefits of an Enchanted Lute. Requires a Campfire nearby. May be placed over an Enchanted Lute to replace it. All camping features share a cooldown of 1 hr. (60 Min Cooldown)",
  "279988": "Use: Places an anvil, and provides all of the benefits of a Sharpening Wheel. Requires a Campfire nearby. May be placed over a Sharpening Wheel to replace it. All camping features share a cooldown of 1 hr.",
  "279989": "Use: Places an Anarchist's Workbench usable for recipes that require it. Requires a Campfire nearby. All camping features share a cooldown of 1 hr.",
  "279990": "Use: Places an Alchemy Laboratory usable for recipes that require it, and provides all of the benefits of a Mana Well. Requires a Campfire nearby. May be placed over a Mana Well to replace it. All camping features share a cooldown of 1 hr.",
