  "anarchist's workbench": "Use: Places an Anarchist's Workbench usable for recipes that require it. Requires a Campfire nearby. All camping features share a cooldown of 1 hr.",
  "hyper deluxe sniper rifle mk xvii": "Use: +21 Ranged Attack Power",
  "saf-t ultra precision scope": "Use: Attaches a permanent scope to a bow, gun, or crossbow that increases its critical strike chance by 2%.",
  "swiftfeather arrow": "Use: Binds when picked up Ammo\tArrow Adds 24.5 damage per second Requires Level 60",
  "swiftstrike shot": "Use: Binds when picked up Ammo\tBullet Damage set by hand\tSpeed 3.00 Requires Level 60",
  "arcane bomb": "Use: Burns 675 to 1125 mana from those in the blast radius and does 50% of the mana drained in damage to the target. Also Silences targets in the blast for 5 sec.",
  "arcanite dragonling": "Use: Activates your Arcanite Dragonling to fight for you for 1 min.",
  "biznicks 247x128 accurascope": "Use: Attaches a permanent scope to a bow or gun that increases its chance to hit by 3%.",
  "bloodvine goggles": "Use: +20 Hit Rating +14 Critical Strike Rating +9 Mana Regeneration",
  "bloodvine lens": "Use: +28 Critical Strike Rating Increases your effective stealth detection level by 2.",
  "core marksman rifle": "Use: +22 Ranged Attack Power +10 Hit Rating",
  "dimensional transporter - mt. hyjal": "Use: Rips the dimensional walls asunder and transports you to Kaylaena's Workshop on Mount Hyjal. Technical problems have a high chance to occur with this mad combination of goblin and gnomish engineering.",
  "ez and saf field transporter: mt. hyjal": "Use: Rips the dimensional walls asunder and transports you to Kaylaena's Workshop on Mount Hyjal. Technical problems have a high chance to occur with this mad combination of goblin and gnomish engineering.",
  "ez-thro dark bomb": "Use: Inflicts 225 to 675 Fire damage and stuns targets in a 5 yd radius for 4 sec. Any damage will break the effect.",
  "ez-thro field transporter: gadgetzan": "Use: Safely transport yourself to Gadgetzan in Tanaris! Emphasis on Safe! Yup, nothing bad could ever happen while using this device!",
  "ez-thro magnetic displacer": "Use: Disrupt a magnetic field between you and your nearby enemy target, knocking you both away. Can only affect targets up to 2 levels higher than you. Some targets cannot be displaced. Targets can only be affected by this effect once every 2 min.",
  "ez-thro mana bomb": "Use: Burns 675 to 1125 mana from those in the blast radius and deals 50% of the mana drained in damage to the target. Also Silences targets in the blast for 5 sec.",
  "field repair bot 74a": "Use: Unfolds into a Field Repair Bot that can repair damaged items and purchase unwanted goods. After 10 minutes its internal motor fails.",
  "flawless arcanite rifle": "Use: +10 Ranged Attack Power",
  "force reactive disk": "Use: When the shield blocks, it releases an electrical charge that damages all nearby enemies. This also has a chance of damaging the shield.",
  "gnomish poultryizer": "Use: Turns the target into a chicken for 15 sec. Well, that is assuming the transmogrification polarity has not been reversed...",
  "gnomish weather machine nyi": "Use: Binds when used \tParts Requires Level 60 Requires Engineering (300) Sell Price: 50s",
  "saf-t emergency ripper: everlook": "Use: Rips the dimensional walls asunder and transports you to Everlook in Winterspring. There are technical problems that sometimes occur, but that's what Goblin Engineering is all about!",
  "saf-t nitro boosts": "Use: Activate a set of jets to increase your movement speed by up to 160%, for up to 8 sec.",
  "saf-t teleport": "Use: Teleport forward 20 yds.",
  "stealthman 52": "Use: Cloaks the user in a stealth field for up to 1 min. Cannot be used in combat. The field lasts for up to 6 sec after moving.",
  "ultra-flash shadow reflector": "Use: Reflects Shadow spells back at their caster for 5 sec.",
  "ultralight goblin glider": "Use: Glide downward through the air for 10 sec while controlling your direction of travel. (5 min cooldown)",
  "ultrasafe rechargeable battery": "Use: Restores 3 charges to a SAF-T or EZ-Thro brand device in your possession that does not involve explosions. It would be completely Unsafe with explosives.",
  "tranquil mechanical yeti": "Use: Right Click to summon and dismiss your Tranquil Mechanical Yeti.",
  "engineering certification": "Use: Unlocks the account-wide title 'The Engineer' upon achieving 300 skill in Engineering.",
  "camp tent": "Use: Builds a tent that allows you and others sitting nearby to increase Rested experience to 5% of a level. No effect if Rested experience already exceeds that value. Requires a Campfire nearby. All camping features share a cooldown of 1 hr.",
